CREATE FUNCTION public.take_all(p_search uuid) RETURNS SETOF public.businesses LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE v_batch uuid := gen_random_uuid(); BEGIN PERFORM 1 FROM public.searches WHERE id=p_search FOR UPDATE; RETURN QUERY WITH chosen AS (SELECT r.id FROM public.reserves r JOIN public.businesses b ON b.id=r.business_id WHERE r.search_id=p_search AND r.shown_at IS NULL AND NOT b.is_lead AND NOT EXISTS(SELECT 1 FROM public.blocked_places x WHERE x.place_id=b.place_id) ORDER BY b.score DESC,b.place_id FOR UPDATE OF r), changed AS (UPDATE public.reserves r SET shown_at=now(),batch_id=v_batch WHERE r.id IN(SELECT id FROM chosen) RETURNING r.business_id) SELECT b.* FROM public.businesses b JOIN changed c ON c.business_id=b.id ORDER BY b.score DESC,b.place_id; END; $$;
REVOKE ALL ON FUNCTION public.take_all(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.take_all(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.finish_search(p_search uuid,p_run text,p_places jsonb) RETURNS SETOF public.businesses LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE s public.searches; p jsonb; b_id uuid; delivered integer; BEGIN SELECT * INTO s FROM public.searches WHERE id=p_search FOR UPDATE; IF s.id IS NULL OR s.status <> 'running' OR s.run_id IS DISTINCT FROM p_run THEN RETURN; END IF; FOR p IN SELECT value FROM jsonb_array_elements(p_places) LOOP IF EXISTS(SELECT 1 FROM public.blocked_places WHERE place_id=p->>'place_id') THEN CONTINUE; END IF; INSERT INTO public.businesses(user_id,place_id,data,website_type,score,city,state,niche) VALUES(auth.uid(),p->>'place_id',p->'data',p->>'website_type',(p->>'score')::double precision,s.city,s.state,s.niche) ON CONFLICT(user_id,place_id) DO NOTHING; SELECT id INTO b_id FROM public.businesses WHERE user_id=auth.uid() AND place_id=p->>'place_id' AND NOT is_lead; IF b_id IS NOT NULL THEN INSERT INTO public.reserves(user_id,search_id,business_id) VALUES(auth.uid(),s.id,b_id) ON CONFLICT(search_id,business_id) DO NOTHING; END IF; END LOOP; SELECT count(*) INTO delivered FROM public.reserves r JOIN public.businesses b ON b.id=r.business_id WHERE r.search_id=s.id AND r.shown_at IS NULL AND NOT b.is_lead; UPDATE public.searches SET status=CASE WHEN delivered=0 THEN 'exhausted' ELSE 'ready' END,updated_at=now() WHERE id=s.id; RETURN QUERY SELECT * FROM public.take_all(s.id); END; $$;